{
  "technical_and_design_decisions": [
    "Java 17+ baseline assumed (consistent with Spring Framework 6.0 requirement stated in spec).",
    "Gradle is retained as the primary build tool since multiple stories reference gradle tasks; Artifactory gradle task is replaced with a command task per U5.",
    "The WebSocket sink is implemented as a native Spring XD-style sink component that supports full-duplex communication over a single TCP connection, leveraging an embedded WebSocket server library (e.g., Jetty/Tyrus) rather than a generic HTTP wrapper.",
    "Uber-jar deployment to HDFS assumes the build artifact is uploaded to a fixed HDFS path, and container bootstrap scripts pull and unpack the jar locally (Hadoop client libs available on container images).",
    "The shared library location is realized as the existing xd/lib convention; classloader conflicts are documented and mitigated via per-module packaging of version-specific jars.",
    "CI work is performed against an existing Bamboo server (used for both EC2 and the new Windows agent) and reuses existing Git/JDK toolchains where possible.",
    "The npm-cache option is treated as a reference inspiration only; the actual implementation will use a Bamboo/Gradle dependency cache rather than copying npm-cache verbatim, because this is a Java/Gradle project, not Node.js."
  ],
  "assumptions": [
    "All estimates are for a single experienced developer with prior Spring XD, Gradle, and Hadoop/HDFS experience; no ramp-up time included.",
    "A workday is 8 productive hours (no meetings/admin overhead).",
    "The custom module referenced in U1/U2/U8 already exists with a basic skeleton; documentation/configuration is incremental rather than greenfield.",
    "An EC2 instance with sufficient resources to enable maxParallelForks and distributed JVM tests is already provisioned and accessible.",
    "A Windows host is already available in the infrastructure where Bamboo agent and required services (Redis, RabbitMQ) can be installed.",
    "Bamboo and SonarQube are already integrated at the build level; configuration changes rather than new server provisioning.",
    "Existing test suite is reasonable in size; flaky test isolation is part of the CI improvements but not full refactoring of the test suite.",
    "No major new third-party license review is required (WebSocket libs and CI cache are OSS and already approved).",
    "PMD/Sonar violations are addressable with minor code/config changes; no architectural rework is required.",
    "The HDFS deployment script reuses existing Hadoop configuration and the cluster is reachable from the CI/build host."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Custom module authoring guide (U1)",
      "activity_description": "Create/update the developer documentation describing how to build a Spring XD custom module following recommended standards, packaging, and patterns.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A2",
      "activity_name": "Uber-jar build configuration (U2)",
      "activity_description": "Extend the Gradle build to produce an uber-jar for a custom module, including manifest, shaded dependencies, and verification that META-INF resources are not overwritten.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A3",
      "activity_name": "HDFS upload and container bootstrap integration (U2)",
      "activity_description": "Implement build-time upload of the uber-jar to a designated HDFS path and modify the container startup logic to fetch and unpack the module so newly arriving containers can deploy it.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A4",
      "activity_name": "WebSocket sink design (U3)",
      "activity_description": "Define the sink contract, message framing, configuration properties (port, path, SSL), connection lifecycle, and backpressure behavior for the native WebSocket sink.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A5",
      "activity_name": "WebSocket sink implementation (U3)",
      "activity_description": "Implement the native WebSocket sink as a Spring XD sink, using an embedded WebSocket server to provide full-duplex communication over a single TCP connection, with proper integration into the XD message bus.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A6",
      "activity_name": "WebSocket sink testing (U3)",
      "activity_description": "Write unit and integration tests covering handshake, message routing, error handling, and concurrent client connections for the WebSocket sink.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A7",
      "activity_name": "CI cache research (U4)",
      "activity_description": "Investigate caching options for previously installed Gradle/npm-style dependencies, evaluate npm-cache as a reference, and recommend an approach compatible with the existing Bamboo/Gradle setup.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A8",
      "activity_name": "CI cache implementation (U4)",
      "activity_description": "Implement the selected dependency caching approach in the CI job definition so repeated builds do not re-download dependencies from the internet.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A9",
      "activity_name": "Distributed JVM test setup (U5)",
      "activity_description": "Enable distributed JVM test execution on the EC2 CI infrastructure, including remote execution configuration and result aggregation.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A10",
      "activity_name": "Migrate artifactory gradle task to command task (U5)",
      "activity_description": "Replace the artifactory Gradle plugin task with a command task that invokes ./gradlew directly, including any required parameter passing and credential handling.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A11",
      "activity_name": "maxParallelForks and embedded hadoop config (U5)",
      "activity_description": "Configure test tasks to run with maxParallelForks for parallel test execution and ensure the embedded Hadoop test profile is disabled for the CI build to avoid resource conflicts.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A12",
      "activity_name": "WARN log and PMD/Sonar violation investigation (U6)",
      "activity_description": "Analyze increased WARN-level log output, trace each warning to its source code, and identify which items are actionable PMD/Sonar violations versus environmental noise.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A13",
      "activity_name": "Fix PMD/Sonar violations (U6)",
      "activity_description": "Implement code and configuration fixes for the identified PMD/Sonar violations surfaced in U6, ensuring the warning log volume is also reduced where appropriate.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A14",
      "activity_name": "Sonar committer notification setup (U6)",
      "activity_description": "Configure SonarQube (and the CI pipeline as needed) so that committers are notified when new violations are introduced or quality gate fails.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A15",
      "activity_name": "Windows Bamboo agent provisioning (U7)",
      "activity_description": "Stand up a Windows agent on the Bamboo server host, install required JDK/PowerShell, register it as a remote agent, and validate connectivity from the Bamboo server.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A16",
      "activity_name": "Windows service and PowerShell configuration (U7)",
      "activity_description": "Install and configure required Windows services (Redis, RabbitMQ, etc.) and ensure PowerShell scripts used by the integration tests are executable and correctly invoked.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A17",
      "activity_name": "Windows commit-triggered CI task (U7)",
      "activity_description": "Create a Bamboo plan/task that runs integration tests on the Windows agent automatically on commit, with appropriate triggers and failure reporting.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A18",
      "activity_name": "Shared library location documentation (U8)",
      "activity_description": "Update developer documentation to describe the recommended xd/lib shared location for jars required by two or more custom modules, including the classloader workaround for version conflicts.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A19",
      "activity_name": "Shared library mechanism (U8)",
      "activity_description": "Implement or refine the runtime/build mechanism that places shared jars in xd/lib and ensures the XD classloader picks them up, while allowing per-module version overrides via bundled jars.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A20",
      "activity_name": "End-to-end integration testing",
      "activity_description": "Run a full end-to-end test combining the WebSocket sink, HDFS-deployed custom module, shared libraries, and both Linux and Windows CI pipelines to verify the increment works as a whole.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A21",
      "activity_name": "Code review, cleanup, and final polish",
      "activity_description": "Conduct self-review and team code review, address review comments, update CHANGELOG/release notes, and apply final polish across the changed areas.",
      "most_likely_effort": 1.5
    }
  ],
  "reported_total": {
    "most_likely_effort": 33.0
  }
}
